using System.Data;
using Microsoft.EntityFrameworkCore;
using TuTuc.Data;
using TuTuc.Models;
namespace TuTuc.Services;
public class CommunityManager(AppDbContext db)
{
 public static readonly string[] TravelStyles=["Tự túc","Phượt","Nghỉ dưỡng","Khám phá văn hóa","Thiên nhiên"];
 public static readonly string[] SharingScopes=["Public","Registered","Connected"];
 public async Task<CommunityPage> Browse(int user,CommunitySearch input)
 {
  var traveler=await IsTraveler(user);var viewer=traveler?user:0;var q=Visible(viewer);
  if(!string.IsNullOrWhiteSpace(input.Q))q=q.Where(x=>x.Destination.Contains(input.Q));if(input.From.HasValue)q=q.Where(x=>x.EndDate.Date>=input.From.Value.Date);if(input.To.HasValue)q=q.Where(x=>x.Date.Date<=input.To.Value.Date);if(input.MaxBudget.HasValue)q=q.Where(x=>x.Budget==0||x.Budget<=input.MaxBudget);if(!string.IsNullOrEmpty(input.TravelStyle))q=q.Where(x=>x.TravelStyle==input.TravelStyle);
  var total=await q.CountAsync();input.Page=Math.Max(1,input.Page);var demands=await q.OrderBy(x=>x.Date).ThenBy(x=>x.Id).Skip((input.Page-1)*20).Take(20).ToListAsync();var cards=new List<DemandCard>();foreach(var demand in demands)cards.Add(await Project(demand,viewer,traveler));return new(){Demands=cards,Search=input,Total=total,Me=user,IsTraveler=traveler};
 }
 IQueryable<Companion> Visible(int viewer)=>db.Companions.AsNoTracking().Where(x=>x.IsPublished&&x.EndDate.Date>=DateTime.Today&&db.Accounts.Any(a=>a.Id==x.OwnerId&&a.IsActive&&a.Role=="Traveler")&&(viewer==0?x.SharingScope=="Public":x.OwnerId!=viewer));
 public async Task<DemandCard?> Detail(int user,int id)
 {
  var traveler=await IsTraveler(user);var viewer=traveler?user:0;var demand=await Visible(viewer).SingleOrDefaultAsync(x=>x.Id==id);
  if(demand==null&&traveler)demand=await db.Companions.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.OwnerId==user);
  return demand==null?null:await Project(demand,viewer,traveler);
 }
 async Task<DemandCard> Project(Companion demand,int viewer,bool registered,bool forceUnconnected=false)
 {
  var owner=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==demand.OwnerId);var profile=await db.UserProfiles.AsNoTracking().SingleOrDefaultAsync(x=>x.OwnerId==demand.OwnerId);var connected=!forceUnconnected&&viewer>0&&await db.Connections.AnyAsync(x=>x.CompanionId==demand.Id&&x.SenderId==viewer&&x.Status=="Đã chấp nhận");
  var own=viewer==demand.OwnerId&&!forceUnconnected;var full=own||demand.SharingScope!="Connected"||connected;var showProfile=own||profile?.SharingScope=="Public"||(profile?.SharingScope=="Registered"&&registered)||(profile?.SharingScope=="Connected"&&connected);var contact=own||(connected&&demand.ShareContact&&profile?.ShareContact==true);
  var requested=viewer>0&&await db.Connections.AnyAsync(x=>x.CompanionId==demand.Id&&x.SenderId==viewer&&(x.Status=="Chờ phản hồi"||x.Status=="Đã chấp nhận"));
  return new(){Id=demand.Id,Destination=demand.Destination,Date=demand.Date,EndDate=demand.EndDate,TravelStyle=demand.TravelStyle,OwnerName=owner.Name,Description=full?demand.Description:null,Budget=full?demand.Budget:null,Wishes=full?demand.Wishes:null,People=full?demand.People:null,Bio=showProfile?owner.Bio:null,Residence=showProfile?profile?.Residence:null,Interests=showProfile?profile?.Interests:null,Email=contact?owner.Email:null,Phone=contact?owner.Phone:null,Limited=!full,Connected=connected,CanConnect=registered&&!own&&!requested&&owner.IsActive&&demand.IsPublished,SharingScope=demand.SharingScope};
 }
 public async Task<CommunityDashboard> Dashboard(int user)
 {
  var demands=await db.Companions.AsNoTracking().Where(x=>x.OwnerId==user).OrderByDescending(x=>x.Id).ToListAsync();var cs=await db.Connections.AsNoTracking().Where(x=>x.SenderId==user||db.Companions.Any(c=>c.Id==x.CompanionId&&c.OwnerId==user)).OrderByDescending(x=>x.CreatedAt).ToListAsync();var list=new List<ConnectionItem>();
  foreach(var c in cs){var d=await db.Companions.AsNoTracking().SingleAsync(x=>x.Id==c.CompanionId);var sender=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==c.SenderId);var other=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==(user==d.OwnerId?c.SenderId:d.OwnerId));var profile=await db.UserProfiles.AsNoTracking().SingleOrDefaultAsync(x=>x.OwnerId==other.Id);var accepted=c.Status=="Đã chấp nhận";var shareProfile=profile?.SharingScope is "Public" or "Registered"||(profile?.SharingScope=="Connected"&&accepted);var shareContact=accepted&&profile?.ShareContact==true&&(other.Id!=d.OwnerId||d.ShareContact);list.Add(new(){Connection=c,Demand=d,SenderName=sender.Name,OtherName=other.Name,OtherBio=shareProfile?other.Bio:null,OtherResidence=shareProfile?profile?.Residence:null,OtherInterests=shareProfile?profile?.Interests:null,OtherEmail=shareContact?other.Email:null,OtherPhone=shareContact?other.Phone:null,Counterpart=await Project(d,user,true),Agreements=await db.CompanionAgreements.AsNoTracking().Where(x=>x.ConnectionId==c.Id).OrderByDescending(x=>x.Revision).ToListAsync()});}return new(){Me=user,Demands=demands,Connections=list};
 }
 public async Task<DemandInput?> Edit(int user,int id){var d=await db.Companions.AsNoTracking().SingleOrDefaultAsync(x=>x.OwnerId==user&&x.Id==id);return d==null?null:new(){Id=d.Id,Destination=d.Destination,Description=d.Description,Date=d.Date,EndDate=d.EndDate,Budget=d.Budget,People=d.People,TravelStyle=d.TravelStyle,Wishes=d.Wishes,SharingScope=d.SharingScope,ShareContact=d.ShareContact,Version=Convert.ToBase64String(d.Version)};}
 public string? ValidateDemand(DemandInput x)=>string.IsNullOrWhiteSpace(x.Destination)||x.Destination.Length>200||string.IsNullOrWhiteSpace(x.Description)||x.Description.Length>2000||x.Date.Date<DateTime.Today||x.EndDate.Date<x.Date.Date||x.Budget<0||x.Budget>1000000000||x.People<1||x.People>20||!TravelStyles.Contains(x.TravelStyle)||!SharingScopes.Contains(x.SharingScope)||(x.Wishes??"").Length>1000?"Kiểm tra điểm đến, khoảng ngày từ hôm nay, nội dung, ngân sách, số người và phạm vi chia sẻ.":null;
 public async Task<DemandPreview> Preview(int user,DemandInput input)
 {
  var account=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==user);var d=new Companion{OwnerId=user,Name=account.Name,Destination=input.Destination,Description=input.Description,Date=input.Date,EndDate=input.EndDate,Budget=input.Budget,People=input.People,TravelStyle=input.TravelStyle,Wishes=input.Wishes??"",SharingScope=input.SharingScope,ShareContact=input.ShareContact};return new(){Draft=input,RegisteredView=await Project(d,0,true,true),PublicView=input.SharingScope=="Public"?await Project(d,0,false,true):null};
 }
 public async Task<CommunityOutcome> Save(int user,DemandInput input)
 {
  var error=ValidateDemand(input);if(error!=null)return new(false,error);await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);if(!await IsTraveler(user))return new(false,"Tài khoản không có quyền công bố nhu cầu.",0,403);var owner=await db.Accounts.SingleAsync(x=>x.Id==user);Companion d;
  if(input.Id==0){d=new(){OwnerId=user};db.Companions.Add(d);}else{d=(await db.Companions.SingleOrDefaultAsync(x=>x.Id==input.Id&&x.OwnerId==user))!;if(d==null)return new(false,"Không tìm thấy nhu cầu.",0,404);if(!Version(d,input.Version))return new(false,"Nhu cầu vừa thay đổi. Hãy tải lại trước khi công bố.",d.Id,409);}
  d.Name=owner.Name;d.Destination=input.Destination.Trim();d.Description=input.Description.Trim();d.Date=input.Date.Date;d.EndDate=input.EndDate.Date;d.Budget=input.Budget;d.People=input.People;d.TravelStyle=input.TravelStyle;d.Wishes=(input.Wishes??"").Trim();d.SharingScope=input.SharingScope;d.ShareContact=input.ShareContact;d.IsPublished=true;
  try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã công bố nhu cầu theo đúng phạm vi đã xem trước.",d.Id);}catch(DbUpdateConcurrencyException){return new(false,"Nhu cầu vừa thay đổi. Nội dung đang soạn được giữ lại.",input.Id,409);}
 }
 public async Task<CommunityOutcome> Stop(int user,int id,string version){var d=await db.Companions.SingleOrDefaultAsync(x=>x.Id==id&&x.OwnerId==user);if(d==null)return new(false,"Không tìm thấy nhu cầu.",0,404);if(!Version(d,version))return new(false,"Phiên bản không hợp lệ.",id,409);d.IsPublished=false;try{await db.SaveChangesAsync();return new(true,"Đã dừng công bố. Lịch sử kết nối được giữ nguyên.",id);}catch(DbUpdateConcurrencyException){return new(false,"Nhu cầu đã thay đổi. Hãy tải lại.",id,409);}}
 public async Task<CommunityOutcome> Connect(int user,int id,string? message)
 {
  if((message??"").Length>1000)return new(false,"Lời giới thiệu tối đa 1000 ký tự.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);if(!await IsTraveler(user))return new(false,"Chỉ tài khoản khách đang hoạt động được kết nối.",0,403);var d=await Visible(user).SingleOrDefaultAsync(x=>x.Id==id);if(d==null)return new(false,"Nhu cầu không còn công bố, ngoài phạm vi hoặc chủ nhu cầu không hoạt động.",0,422);if(d.OwnerId==user)return new(false,"Không thể gửi đề nghị cho chính bạn.",0,422);if(await db.Connections.AnyAsync(x=>x.CompanionId==id&&x.SenderId==user&&(x.Status=="Chờ phản hồi"||x.Status=="Đã chấp nhận")))return new(false,"Bạn đã có đề nghị đang chờ hoặc kết nối được chấp nhận cho nhu cầu này.",0,409);
  var c=new Connection{CompanionId=id,SenderId=user,Message=(message??"").Trim()};db.Connections.Add(c);try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã gửi đề nghị, chờ người nhận phản hồi.",c.Id);}catch(DbUpdateException){return new(false,"Đề nghị đã được gửi đồng thời trước đó. Hãy tải lại.",0,409);}
 }
 public async Task<CommunityOutcome> Respond(int user,int id,string version,string decision)
 {
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var c=await db.Connections.SingleOrDefaultAsync(x=>x.Id==id);if(c==null)return new(false,"Không tìm thấy đề nghị.",0,404);var d=await db.Companions.SingleAsync(x=>x.Id==c.CompanionId);if(user!=d.OwnerId&&user!=c.SenderId)return new(false,"Không tìm thấy đề nghị.",0,404);if(c.Status!="Chờ phản hồi")return new(false,"Đề nghị đã được xử lý: "+c.Status,id,409);if(!Version(c,version))return new(false,"Phiên bản đề nghị không hợp lệ.",id,409);
  if(decision=="accept"&&user==d.OwnerId){if(!await BothActive(c,d)){c.Status="Hết hiệu lực";c.RespondedAt=DateTime.UtcNow;await db.SaveChangesAsync();await tx.CommitAsync();return new(false,"Một bên đã ngừng tài khoản. Đề nghị không còn hiệu lực.",id,422);}c.Status="Đã chấp nhận";}
  else if(decision=="reject"&&user==d.OwnerId)c.Status="Từ chối";else if(decision=="withdraw"&&user==c.SenderId)c.Status="Đã rút";else return new(false,"Bạn không có quyền thực hiện phản hồi này.",id,403);c.RespondedAt=DateTime.UtcNow;
  try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã cập nhật đề nghị. Chấp nhận kết nối chưa phải thỏa thuận đi cùng.",id);}catch(DbUpdateConcurrencyException){return new(false,"Đề nghị đã thay đổi. Hãy tải lại.",id,409);}
 }
 public async Task<AgreementPage?> AgreementEditor(int user,int connectionId)
 {
  var dashboard=await Dashboard(user);var item=dashboard.Connections.SingleOrDefault(x=>x.Connection.Id==connectionId&&x.Connection.Status=="Đã chấp nhận");if(item==null)return null;var pending=item.Agreements.FirstOrDefault(x=>x.Status=="Chờ xác nhận");var current=pending??item.Agreements.FirstOrDefault(x=>x.Status=="Đã xác nhận");var d=item.Demand;return new(){Item=item,Draft=new(){ConnectionId=connectionId,BaseRevision=item.Agreements.Select(x=>x.Revision).DefaultIfEmpty().Max(),PendingId=pending?.Id,PendingVersion=pending==null?null:Convert.ToBase64String(pending.Version),Start=current?.Start??d.Date,End=current?.End??d.EndDate,Destination=current?.Destination??d.Destination,Budget=current?.Budget??d.Budget,CostSharing=current?.CostSharing??"",Scope=current?.Scope??"",Content=current?.Content}};
 }
 public async Task<CommunityOutcome> Propose(int user,AgreementInput input)
 {
  if(string.IsNullOrWhiteSpace(input.Destination)||input.Destination.Length>200||input.Start.Date<DateTime.Today||input.End.Date<input.Start.Date||input.Budget<0||input.Budget>1000000000||string.IsNullOrWhiteSpace(input.CostSharing)||input.CostSharing.Length>1000||string.IsNullOrWhiteSpace(input.Scope)||input.Scope.Length>1000||(input.Content??"").Length>2000)return new(false,"Nhập nơi đến, khoảng ngày hợp lệ, ngân sách, cách chia chi phí và phạm vi đi cùng.");
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var pair=await Pair(user,input.ConnectionId);if(pair==null)return new(false,"Không tìm thấy kết nối đã chấp nhận của bạn.",0,404);var(c,d)=pair.Value;if(!await BothActive(c,d))return new(false,"Cả hai tài khoản phải đang hoạt động để đồng ý nội dung mới.",0,422);var versions=await db.CompanionAgreements.Where(x=>x.ConnectionId==c.Id).OrderByDescending(x=>x.Revision).ToListAsync();if(Ended(versions))return new(false,"Thỏa thuận đã kết thúc, không thể mở lại bằng đề nghị cũ.",0,422);if(versions.Select(x=>x.Revision).DefaultIfEmpty().Max()!=input.BaseRevision)return new(false,"Đã có phiên bản mới. Hãy tải lại trước khi đề xuất.",0,409);var pending=versions.FirstOrDefault(x=>x.Status=="Chờ xác nhận");if(pending?.Kind=="Cùng ngừng")return new(false,"Đang có đề nghị cùng ngừng. Phản hồi hoặc sử dụng quyền rút riêng.",0,409);
  if(pending!=null&&(input.PendingId!=pending.Id||!SameVersion(pending.Version,input.PendingVersion)))return new(false,"Đề xuất đang chờ đã thay đổi. Hãy xem phiên bản hiện tại.",0,409);var active=versions.FirstOrDefault(x=>x.Status=="Đã xác nhận");if(active!=null&&SameContent(active,input))return new(false,"Nội dung trùng thỏa thuận đang hiệu lực, không tạo phiên bản mới.",0,422);
  if(pending!=null){pending.Status="Đã thay thế";pending.Reason="Đã có đề xuất nội dung mới";await db.SaveChangesAsync();}
  var a=new CompanionAgreement{ConnectionId=c.Id,Revision=input.BaseRevision+1,ProposerId=user,Start=input.Start.Date,End=input.End.Date,Destination=input.Destination.Trim(),Budget=input.Budget,CostSharing=input.CostSharing.Trim(),Scope=input.Scope.Trim(),Content=(input.Content??"").Trim()};db.CompanionAgreements.Add(a);Notify(Other(user,c,d),"Thỏa thuận đồng hành chờ xác nhận","Có phiên bản mới cần bạn xem và phản hồi.");await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã gửi phiên bản mới. Thỏa thuận cũ giữ hiệu lực đến khi hai bên thống nhất.",c.Id);
 }
 public async Task<CommunityOutcome> EndProposal(int user,int connectionId,int baseRevision)
 {
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var pair=await Pair(user,connectionId);if(pair==null)return new(false,"Không tìm thấy kết nối.",0,404);var(c,d)=pair.Value;if(!await BothActive(c,d))return new(false,"Một bên không còn hoạt động. Bạn vẫn có thể rút khỏi thỏa thuận.",0,422);var versions=await db.CompanionAgreements.Where(x=>x.ConnectionId==c.Id).ToListAsync();if(Ended(versions))return new(false,"Thỏa thuận đã kết thúc.",0,422);if(versions.Any(x=>x.Status=="Chờ xác nhận"))return new(false,"Đang có đề xuất chờ. Bạn có thể phản hồi hoặc rút riêng.",0,409);if(versions.Select(x=>x.Revision).DefaultIfEmpty().Max()!=baseRevision)return new(false,"Đã có phiên bản mới. Hãy tải lại.",0,409);var active=versions.SingleOrDefault(x=>x.Status=="Đã xác nhận");if(active==null)return new(false,"Không có thỏa thuận đang hiệu lực.",0,409);
  db.CompanionAgreements.Add(new(){ConnectionId=c.Id,Revision=baseRevision+1,ProposerId=user,Kind="Cùng ngừng",Start=active.Start,End=active.End,Destination=active.Destination,Budget=active.Budget,CostSharing=active.CostSharing,Scope=active.Scope,Content=active.Content});Notify(Other(user,c,d),"Đề nghị cùng ngừng đồng hành","Thỏa thuận hiện tại tiếp tục có hiệu lực trong lúc chờ phản hồi.");await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã gửi đề nghị cùng ngừng. Bạn vẫn có quyền rút riêng ngay.",c.Id);
 }
 public async Task<CommunityOutcome> Agreement(int user,int id,int revision,string version,string decision,string? reason)
 {
  if(decision is not("accept" or "reject"))return new(false,"Lựa chọn không hợp lệ.");if(decision=="reject"&&string.IsNullOrWhiteSpace(reason))return new(false,"Phải nhập lý do từ chối.");if((reason??"").Length>500)return new(false,"Lý do tối đa 500 ký tự.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var a=await db.CompanionAgreements.SingleOrDefaultAsync(x=>x.Id==id);if(a==null)return new(false,"Không tìm thấy phiên bản.",0,404);var pair=await Pair(user,a.ConnectionId);if(pair==null)return new(false,"Không tìm thấy thỏa thuận.",0,404);var(c,d)=pair.Value;if(a.ProposerId==user)return new(false,"Bạn không thể tự xác nhận đề xuất của mình.",c.Id,403);if(a.Status!="Chờ xác nhận"||a.Revision!=revision||!Version(a,version))return new(false,"Phiên bản đã thay đổi hoặc đã được xử lý.",c.Id,409);var versions=await db.CompanionAgreements.Where(x=>x.ConnectionId==c.Id).ToListAsync();if(Ended(versions))return new(false,"Thỏa thuận đã kết thúc. Đề xuất cũ không thể mở lại.",c.Id,422);if(!await BothActive(c,d))return new(false,"Một bên không còn hoạt động. Không tạo sự đồng ý mới.",c.Id,422);
  a.RespondedBy=user;a.RespondedAt=DateTime.UtcNow;a.Reason=(reason??"").Trim();if(decision=="reject")a.Status="Từ chối";else{var active=versions.SingleOrDefault(x=>x.Status=="Đã xác nhận");if(a.Kind=="Cùng ngừng"){if(active==null)return new(false,"Không còn thỏa thuận hiệu lực để cùng ngừng.",c.Id,409);active.Status="Đã ngừng";active.EndedBy=user;active.EndedAt=DateTime.UtcNow;a.Status="Đã ngừng";a.EndedBy=user;a.EndedAt=DateTime.UtcNow;}else{if(active!=null){active.Status="Đã thay thế";await db.SaveChangesAsync();}a.Status="Đã xác nhận";}}
  Notify(a.ProposerId,"Thỏa thuận đồng hành: "+a.Status,"Bên còn lại đã phản hồi đúng phiên bản "+a.Revision+".");if(decision=="accept")Notify(user,"Thỏa thuận đồng hành: "+a.Status,"Bạn đã xác nhận phiên bản "+a.Revision+".");try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,decision=="reject"?"Đã từ chối đề xuất. Thỏa thuận cũ không đổi.":"Đã ghi nhận thỏa thuận: "+a.Status+".",c.Id);}catch(DbUpdateConcurrencyException){return new(false,"Phiên bản vừa thay đổi. Hãy tải lại.",c.Id,409);}
 }
 public async Task<CommunityOutcome> Withdraw(int user,int connectionId,string version,string? reason)
 {
  if((reason??"").Length>500)return new(false,"Lý do tối đa 500 ký tự.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var pair=await Pair(user,connectionId);if(pair==null)return new(false,"Không tìm thấy thỏa thuận của bạn.",0,404);var(c,d)=pair.Value;var versions=await db.CompanionAgreements.Where(x=>x.ConnectionId==c.Id).ToListAsync();var active=versions.SingleOrDefault(x=>x.Status=="Đã xác nhận");if(active==null||!Version(active,version))return new(false,"Không còn đúng phiên bản thỏa thuận hiệu lực để rút.",c.Id,409);
  active.Status="Một bên đã rút";active.EndedBy=user;active.EndedAt=DateTime.UtcNow;active.Reason=(reason??"").Trim();foreach(var pending in versions.Where(x=>x.Status=="Chờ xác nhận")){pending.Status="Đã thay thế";pending.Reason="Thỏa thuận đã kết thúc do một bên rút";}Notify(Other(user,c,d),"Một bên đã rút khỏi đồng hành","Thỏa thuận đã kết thúc ngay. Việc chưa xem thông báo không giữ thỏa thuận hiệu lực; dịch vụ đã đặt không tự bị hủy.");try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Bạn đã rút khỏi đồng hành. Thỏa thuận kết thúc ngay, không chờ bên còn lại.",c.Id);}catch(DbUpdateConcurrencyException){return new(false,"Thỏa thuận vừa thay đổi. Hãy tải lại trước khi rút.",c.Id,409);}
 }
 async Task<(Connection,Companion)?> Pair(int user,int id){if(!await IsTraveler(user))return null;var c=await db.Connections.SingleOrDefaultAsync(x=>x.Id==id&&x.Status=="Đã chấp nhận");if(c==null)return null;var d=await db.Companions.SingleAsync(x=>x.Id==c.CompanionId);return c.SenderId==user||d.OwnerId==user?(c,d):null;}
 Task<bool> IsTraveler(int user)=>db.Accounts.AnyAsync(x=>x.Id==user&&x.Role=="Traveler"&&x.IsActive);
 async Task<bool> BothActive(Connection c,Companion d)=>await db.Accounts.CountAsync(x=>(x.Id==c.SenderId||x.Id==d.OwnerId)&&x.Role=="Traveler"&&x.IsActive)==2;
 static int Other(int user,Connection c,Companion d)=>user==d.OwnerId?c.SenderId:d.OwnerId;
 static bool Ended(IEnumerable<CompanionAgreement> versions)=>versions.Any(x=>x.Kind=="Nội dung"&&(x.Status=="Đã ngừng"||x.Status=="Một bên đã rút"));
 static bool SameContent(CompanionAgreement a,AgreementInput b)=>a.Start.Date==b.Start.Date&&a.End.Date==b.End.Date&&a.Destination==b.Destination.Trim()&&a.Budget==b.Budget&&a.CostSharing==b.CostSharing.Trim()&&a.Scope==b.Scope.Trim()&&a.Content==(b.Content??"").Trim();
 static bool SameVersion(byte[] version,string? value){try{return version.SequenceEqual(Convert.FromBase64String(value??""));}catch(FormatException){return false;}}
 bool Version<T>(T entity,string? version)where T:class{if(version==null)return false;try{var bytes=Convert.FromBase64String(version);if(bytes.Length!=8||!db.Entry(entity).Property<byte[]>("Version").CurrentValue.SequenceEqual(bytes))return false;db.Entry(entity).Property("Version").OriginalValue=bytes;return true;}catch(FormatException){return false;}}
 void Notify(int owner,string title,string text)=>db.Notifications.Add(new(){OwnerId=owner,Title=title,Description=text,Url="/Community/Dashboard"});
}


